#!/usr/bin/env bash
# Bounded iSTA re-check for the FFN1 8x16 compute core, noexpr netlist only.
#
# Scope / honesty boundary:
#   - Object: kwt_systolic_cacc_tile (compute core) only.
#   - Library: icsprout55 example library (ss/rcworst/1.08V/125C), NOT the
#     contest PDK. No SRAM macros, DMA, E203, bus/NICE, or controller.
#   - A successful run is an *exploratory* timing report. It is not a signoff
#     result and must never be quoted as proof of 150 MHz.
#   - The netlist is generated by the existing run_ffn1_8x16_sta.sh path. This
#     script does NOT re-synthesize; it only runs iSTA with a hard timeout.
#
# Usage:
#   NETLIST=/tmp/kwt-8x16-sta/systolic_ics_noexpr.v \
#   SDC=/tmp/kwt-8x16-sta/ffn1_8x16_150mhz.sdc \
#     bash hardware/synth/run_sta_noexpr_followup.sh
#
# Exit codes:
#   0   iSTA parsed the netlist, applied the clock, and produced a report
#       (timing may still be VIOLATED; read TIMING_MET in the output).
#   2   missing input/tool
#   3   noexpr netlist still contains assign statements
#   4   iSTA exited 0 but the report/clock/slack evidence is missing
#   124 iSTA hit the timeout
#   *   iSTA's own non-zero exit code is passed through unchanged
set -euo pipefail

repo_dir="$(cd "$(dirname "$0")/../.." && pwd)"
out_dir="${OUT:-/tmp/kwt-8x16-sta-followup}"
top="kwt_systolic_cacc_tile"
clock_mhz="${CLK_FREQ_MHZ:-150}"
timeout_sec="${TIMEOUT_SEC:-240}"

# Reuse the already-generated noexpr netlist by default; do not re-synthesize.
netlist="${NETLIST:-/tmp/kwt-8x16-sta/systolic_ics_noexpr.v}"
sdc="${SDC:-/tmp/kwt-8x16-sta/ffn1_8x16_150mhz.sdc}"

YOSYS_STA="${YOSYS_STA:-/home/yang/yosys-sta}"
IEDA="${IEDA:-$YOSYS_STA/bin/iEDA}"
STA_TCL="${STA_TCL:-$YOSYS_STA/scripts/sta.tcl}"
PDK="${PDK:-icsprout55}"

for f in "$netlist" "$sdc" "$STA_TCL"; do
    if [[ ! -f "$f" ]]; then
        echo "Missing required file: $f" >&2
        echo "Regenerate the noexpr netlist with the existing synthesis script, bounded:" >&2
        echo "  SYNTH_OUT=/tmp/kwt-8x16-sta timeout 240 bash hardware/synth/run_ffn1_8x16_sta.sh --skip-nangate" >&2
        echo "Do not run an unbounded re-synthesis." >&2
        exit 2
    fi
done
if [[ ! -x "$IEDA" ]]; then
    echo "Missing iSTA binary: $IEDA" >&2
    exit 2
fi

# The noexpr netlist is the whole point of this route: iSTA aborts on the
# default write_verilog aliases. Refuse to proceed if assign statements exist.
assign_count="$(grep -c 'assign' "$netlist" || true)"
if [[ "$assign_count" -ne 0 ]]; then
    echo "Netlist still contains $assign_count assign statement(s): $netlist" >&2
    echo "This is not the -noexpr netlist; refusing to run." >&2
    exit 3
fi
if ! grep -q 'create_clock' "$sdc" || ! grep -q 'get_ports clk' "$sdc"; then
    echo "SDC does not constrain port clk: $sdc" >&2
    exit 2
fi

mkdir -p "$out_dir"
cd "$repo_dir"

# iSTA writes reports to dirname(NETLIST). Use a symlink with a name different
# from the top module so iEDA's own <top>.v output cannot overwrite the input.
netlist_link="$out_dir/$(basename "$netlist")"
ln -sfn "$netlist" "$netlist_link"
report="$out_dir/${top}.rpt"
log="$out_dir/${top}_${clock_mhz}mhz_noexpr_sta.log"
rm -f "$report" "$log"

{
    echo "date: $(date -Iseconds)"
    echo "clock_mhz: $clock_mhz (requested constraint only, not a proven result)"
    echo "timeout_sec: $timeout_sec"
    echo "iEDA: $("$IEDA" -v 2>&1 | head -1)"
    echo "netlist: $netlist"
    echo "netlist_sha256: $(sha256sum "$netlist" | awk '{print $1}')"
    echo "sdc: $sdc"
    echo "sdc_sha256: $(sha256sum "$sdc" | awk '{print $1}')"
    echo "pdk: $PDK (example library only)"
} | tee "$out_dir/${top}_noexpr_versions.txt"

echo "== bounded iSTA: timeout ${timeout_sec}s =="
set +e
timeout "$timeout_sec" "$IEDA" -script "$STA_TCL" "$sdc" "$netlist_link" "$top" "$PDK" \
    > "$log" 2>&1
sta_rc=$?
set -e

if [[ "$sta_rc" -eq 124 ]]; then
    echo "iSTA TIMED OUT after ${timeout_sec}s; see $log" >&2
    echo "No timing conclusion. Do NOT claim ${clock_mhz} MHz." >&2
    exit 124
fi
if [[ "$sta_rc" -ne 0 ]]; then
    echo "iSTA FAILED with exit code $sta_rc; see $log" >&2
    echo "Do NOT claim ${clock_mhz} MHz: no timing report was produced." >&2
    exit "$sta_rc"
fi
if ! grep -q 'The timing engine run success' "$log"; then
    echo "iSTA exited 0 but did not report a successful timing engine run: $log" >&2
    exit 4
fi
if [[ ! -s "$report" ]]; then
    echo "iSTA exited 0 but produced no report: $report" >&2
    exit 4
fi
if ! grep -q 'create clock clk for pin/port: clk' "$log"; then
    echo "Clock was not applied to port clk; report is not usable: $log" >&2
    exit 4
fi

max_row="$(grep -E '^\|.*\| clk *\| max *\|' "$report" | head -1 || true)"
min_row="$(grep -E '^\|.*\| clk *\| min *\|' "$report" | head -1 || true)"
if [[ -z "$max_row" ]]; then
    echo "No clk/max timing row found in $report" >&2
    exit 4
fi

max_slack="$(printf '%s\n' "$max_row" | awk -F'|' '{gsub(/ /,"",$8); print $8}')"
max_freq="$(printf '%s\n' "$max_row" | awk -F'|' '{gsub(/ /,"",$9); print $9}')"
min_slack=""
if [[ -n "$min_row" ]]; then
    min_slack="$(printf '%s\n' "$min_row" | awk -F'|' '{gsub(/ /,"",$8); print $8}')"
fi
if ! [[ "$max_slack" =~ ^-?[0-9]+([.][0-9]+)?$ ]]; then
    echo "Could not parse a numeric max slack from $report" >&2
    exit 4
fi

timing_met="no"
if awk -v s="$max_slack" -v m="${min_slack:-0}" 'BEGIN{exit !(s>=0 && m>=0)}'; then
    timing_met="yes-at-this-constraint-only"
fi

echo
echo "== iSTA completed =="
echo "report: $report"
echo "log: $log"
echo "assigns in netlist: $assign_count"
echo "worst max slack (ns): $max_slack"
echo "worst min slack (ns): ${min_slack:-n/a}"
echo "reported max frequency (MHz): $max_freq"
echo "TIMING_MET=$timing_met"
echo "SCOPE: example library + compute core only; exploratory, not signoff;"
echo "       no SRAM/DMA/E203/bus/controller, not the contest PDK."
echo "Do NOT claim 150 MHz from this report."
